import type { DrugInput } from "@/lib/schema";

/**
 * Product depth: dosing, toxicity, access, regulatory events, and mechanism steps.
 * Kept separate from drugs.ts so the core records stay readable; merged in drugs.ts.
 *
 * Sources: toxicity percentages are read from the US prescribing information on DailyMed
 * (setid links below) or the pivotal publication; where a figure could not be read from a
 * source the field is omitted rather than estimated. Regulatory event dates come from FDA
 * approval notifications and company announcements. Prices only where publicly disclosed.
 */
export type DrugDepth = Pick<DrugInput, "dosing" | "toxicity" | "access" | "regulatoryEvents" | "mechanismSteps">;

const DM = (setid: string) => `https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=${setid}`;
const FDA_ONC = "https://www.fda.gov/drugs/resources-information-approved-drugs/oncology-cancer-hematologic-malignancies-approval-notifications";
const CMS_PARTB = "https://www.cms.gov/medicare/payment/part-b-drugs/asp-pricing-files";
const NICE = "https://www.nice.org.uk/guidance/published?ngt=Technology%20appraisal%20guidance";

type Ev = NonNullable<DrugDepth["regulatoryEvents"]>[number];
const ev = (date: string, type: Ev["type"], region: string, note: string, source?: string): Ev => ({ date, type, region, note, source: source ?? FDA_ONC });
type Tx = NonNullable<DrugDepth["toxicity"]>[number];
const tx = (event: string, anyGradePct?: number, grade3PlusPct?: number, source?: string, note?: string): Tx => ({ event, anyGradePct, grade3PlusPct, source, note });

const US_PARTB = (asst?: string) => ({ country: "US", reimbursement: "Medicare Part B (physician-administered); commercial plans per formulary", assistance: asst, source: CMS_PARTB, asOf: "2026-09-06" });
const US_PARTD = (asst?: string) => ({ country: "US", reimbursement: "Medicare Part D (oral); commercial plans per formulary, often with prior authorisation", assistance: asst, source: CMS_PARTB, asOf: "2026-09-06" });
const UK_NICE = (note: string) => ({ country: "UK", reimbursement: `NICE: ${note}`, source: NICE, asOf: "2026-09-06" });

// Mechanism step templates.
const ADC_STEPS = (target: string, payload: string, bystander = true) => [
  `Antibody binds ${target} on the tumour cell surface`,
  "Receptor-ADC complex is internalised by endocytosis",
  "Trafficked to the lysosome; linker is cleaved or antibody degraded",
  `${payload} is released inside the cell`,
  payload.match(/DXd|SN-38|exatecan|belotecan|TOP1|camptothecin/i) ? "Topoisomerase-I is trapped on DNA; replication forks collapse into double-strand breaks" : payload.match(/MMAE|MMAF|DM1|DM4|maytans|auristatin/i) ? "Microtubule assembly is blocked; mitosis arrests" : "DNA is damaged (crosslinks or double-strand breaks)",
  "Tumour cell dies by apoptosis",
  ...(bystander ? ["Membrane-permeable payload diffuses to kill neighbouring antigen-negative cells (bystander effect)"] : []),
];
const PD1_STEPS = (target: string) => [
  `Antibody binds ${target}`,
  "PD-1/PD-L1 engagement between T cell and tumour is blocked",
  "Exhausted tumour-reactive T cells regain effector function",
  "Interferon-γ and cytotoxic granules are released at the tumour",
  "Tumour cells are killed; memory T cells persist",
];
const TKI_STEPS = (target: string, extra?: string) => [
  `Oral drug is absorbed and reaches the tumour`,
  `Binds the ATP pocket (or allosteric site) of ${target}`,
  "Phosphorylation of downstream substrates stops",
  extra ?? "Proliferation and survival signalling collapse",
  "Oncogene-addicted cells arrest and undergo apoptosis",
];
const RLT_STEPS = (target: string, particle: string) => [
  `Radioligand circulates and binds ${target} on tumour cells`,
  "Ligand is internalised or retained at the membrane",
  `${particle} emissions deposit energy within a short range`,
  "Clustered DNA double-strand breaks form in the tumour cell and its neighbours (crossfire)",
  "Cells die; unbound ligand is cleared via the kidneys",
];
const TCE_STEPS = (target: string) => [
  `One arm binds ${target} on the tumour cell`,
  "The other arm binds CD3 on any passing T cell",
  "An artificial immune synapse forms, independent of MHC",
  "The T cell releases perforin and granzymes into the tumour cell",
  "Tumour cell dies; cytokines are released (source of CRS)",
];
const CAR_STEPS = (target: string) => [
  "Patient's T cells are collected by leukapheresis",
  `Cells are engineered to express a CAR against ${target} and expanded`,
  "Patient receives lymphodepleting chemotherapy",
  "CAR-T cells are infused, home to tumour, and expand",
  `CAR binds ${target}; T cell kills the tumour cell and proliferates`,
  "Memory CAR-T cells persist and patrol",
];

